CREATE TABLE IF NOT EXISTS reward_settings(id INTEGER PRIMARY KEY CHECK(id=1),value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS item_wallet(member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,kind TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),PRIMARY KEY(member_id,kind));
CREATE TABLE IF NOT EXISTS item_batches(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS item_gifts(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES item_batches(id),member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,kind TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),created_at TEXT NOT NULL,received_at TEXT);
CREATE INDEX IF NOT EXISTS item_gifts_owner ON item_gifts(member_id,created_at);
CREATE TABLE IF NOT EXISTS item_ledger(id INTEGER PRIMARY KEY,member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,kind TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lottery_boosts(member_id INTEGER PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE,remaining INTEGER NOT NULL CHECK(remaining>=0));
CREATE TABLE IF NOT EXISTS bath_completions(day TEXT NOT NULL,member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,revision TEXT NOT NULL,start INTEGER NOT NULL,duration INTEGER NOT NULL,reported_at TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(day,member_id));
CREATE TABLE IF NOT EXISTS weekly_rewards(week TEXT NOT NULL,member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,kind TEXT NOT NULL,quantity INTEGER NOT NULL,claimed_at TEXT NOT NULL,PRIMARY KEY(week,member_id));

CREATE TABLE IF NOT EXISTS item_actions(id TEXT PRIMARY KEY,member_id INTEGER NOT NULL REFERENCES members(id) ON DELETE CASCADE,kind TEXT NOT NULL);
